function agent_events_assign_hashes().definition:
CREATE OR REPLACE FUNCTION public.agent_events_assign_hashes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  SELECT event_hash INTO NEW.prev_hash
    FROM agent_events
    WHERE run_id = NEW.run_id AND seq < NEW.seq
    ORDER BY seq DESC
    LIMIT 1;
  NEW.prev_hash := coalesce(NEW.prev_hash, '');
  NEW.event_hash := agent_event_hash(NEW.prev_hash, NEW.payload);
  RETURN NEW;
END;
$function$

function audit_trail_assign().definition:
CREATE OR REPLACE FUNCTION public.audit_trail_assign()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
BEGIN
  -- 0x766967696C415544, "vigilAUD": the trail's own key.
  PERFORM pg_advisory_xact_lock(8532464671515563332);
  SELECT t.seq, t.entry_hash INTO NEW.seq, NEW.prev_hash
    FROM public.audit_trail t ORDER BY t.seq DESC LIMIT 1;
  IF NOT FOUND THEN
    SELECT a.seq, a.entry_hash INTO NEW.seq, NEW.prev_hash FROM public.audit_trail_anchor a;
  END IF;
  NEW.seq := NEW.seq + 1;
  NEW.entry_hash := public.audit_trail_hash(
    NEW.prev_hash, NEW.seq, NEW.occurred_at, NEW.late, NEW.payload);
  RETURN NEW;
END;
$function$

function audit_trail_delete_prefix(bigin.definition:
CREATE OR REPLACE FUNCTION public.audit_trail_delete_prefix(through bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  last_hash text;
  removed bigint;
BEGIN
  PERFORM pg_advisory_xact_lock(8532464671516545614);
  PERFORM pg_advisory_xact_lock(8532464671515563332);
  SELECT entry_hash INTO last_hash FROM public.audit_trail WHERE seq = through;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'audit trail has no entry %', through;
  END IF;
  DELETE FROM public.audit_trail WHERE seq <= through;
  GET DIAGNOSTICS removed = ROW_COUNT;
  UPDATE public.audit_trail_anchor SET seq = through, entry_hash = last_hash;
  RETURN removed;
END;
$function$

